import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.C4zpkcTP.js";const u=JSON.parse('{"title":"Upgrading","description":"Upgrade Laravel New Relic from v1 to v4. New class names, config/newrelic.php, new publish tags and a required license key.","frontmatter":{"title":"Upgrading","description":"Upgrade Laravel New Relic from v1 to v4. New class names, config/newrelic.php, new publish tags and a required license key."},"headers":[],"relativePath":"laravel-newrelic/upgrading.md","filePath":"laravel-newrelic/upgrading.md"}'),c={name:"laravel-newrelic/upgrading.md"};function d(n,e,i,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="upgrading-to-v4-from-v1" tabindex="-1">Upgrading to v4 from v1 <a class="header-anchor" href="#upgrading-to-v4-from-v1" aria-label="Permalink to &quot;Upgrading to v4 from v1&quot;">​</a></h1><p>Versions 2 and 3 were never released; v4.0.0 follows v1.0.0 directly so every Laranex package shares the same major.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-newrelic:^4.0</span></span></code></pre></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>PHP 8.1+ and Laravel 10 to 13 (v1 allowed PHP 7.4). Monolog <code>^3.6</code> is required (v1 allowed <code>^3.0</code>), and <code>ext-curl</code> is now a Composer requirement instead of a check when the handler is built. The New Relic PHP agent stays optional: without it, logs still ship and the transaction listeners do nothing.</p><h2 id="renamed-classes" tabindex="-1">Renamed classes <a class="header-anchor" href="#renamed-classes" aria-label="Permalink to &quot;Renamed classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Before (v1)</th><th>After (v4)</th></tr></thead><tbody><tr><td><code>LaravelNewrelicServiceProvider</code></td><td><code>NewRelicServiceProvider</code></td></tr><tr><td><code>LaravelNewrelicLogger</code></td><td><code>Logging\\NewRelicLogger</code></td></tr><tr><td><code>Handler</code> / <code>AbstractHandler</code></td><td><code>Logging\\NewRelicHandler</code></td></tr><tr><td><code>Formatter</code> / <code>AbstractFormatter</code></td><td><code>Logging\\NewRelicFormatter</code></td></tr><tr><td><code>Processor</code></td><td><code>Logging\\NewRelicProcessor</code></td></tr><tr><td><code>Listeners\\StartNewrelicWebTransaction</code></td><td><code>Listeners\\StartWebTransaction</code></td></tr><tr><td><code>Listeners\\StopNewrelicWebTransaction</code></td><td><code>Listeners\\EndTransaction</code></td></tr><tr><td><code>Listeners\\RestartNewrelicTransaction</code></td><td>None: the New Relic agent names queue job transactions itself</td></tr></tbody></table><p>All classes are in the <code>Laranex\\LaravelNewrelic</code> namespace. <code>EventMap</code> and <code>LaravelNewrelic</code> were removed.</p><ul><li>The service provider is auto-discovered; update it only if you registered it manually.</li><li>In a custom channel, replace <code>&#39;via&#39; =&gt; Laranex\\LaravelNewrelic\\LaravelNewrelicLogger::class</code> with <code>&#39;via&#39; =&gt; Laranex\\LaravelNewrelic\\Logging\\NewRelicLogger::class</code>.</li><li><code>NewRelicHandler</code> takes a <code>Contracts\\LogTransport</code> and the license key in its constructor instead of <code>setLicenseKey()</code> / <code>setHost()</code>.</li><li>The listeners depend on <code>Contracts\\Agent</code> and no longer call <code>newrelic_*</code> functions directly.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The config file moved from <code>config/laravel-newrelic.php</code> to <code>config/newrelic.php</code>, and the publish tag changed from <code>laravel-newrelic</code> to <code>newrelic-config</code> (or <code>newrelic</code>).</p><ul><li>Rename a published <code>config/laravel-newrelic.php</code> to <code>config/newrelic.php</code>, or re-publish it with <code>php artisan vendor:publish --tag=&quot;newrelic-config&quot;</code>.</li><li>Replace <code>config(&#39;laravel-newrelic.*&#39;)</code> reads with <code>config(&#39;newrelic.*&#39;)</code>.</li><li><code>NEW_RELIC_API_KEY</code> still works, but <code>NEW_RELIC_LICENSE_KEY</code> is the new name.</li><li>New keys: <code>host</code> (<code>NEW_RELIC_LOG_HOST</code>), <code>app_name</code> (<code>NEW_RELIC_APP_NAME</code>), <code>transactions.octane</code> (<code>NEW_RELIC_OCTANE_TRANSACTIONS</code>) and <code>transport.timeout</code> / <code>transport.retries</code> (<code>NEW_RELIC_LOG_TIMEOUT</code> / <code>NEW_RELIC_LOG_RETRIES</code>). See <a href="./usage.html#configuration">Usage</a>.</li></ul><h2 id="behavior-changes" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h2><ul><li><strong>Missing license key.</strong> v1 posted logs with a <code>NO_LICENSE_KEY_FOUND</code> key. v4 throws when the channel is built, and Laravel falls back to its emergency logger. Set <code>NEW_RELIC_LICENSE_KEY</code> or configure the agent&#39;s <code>newrelic.license</code>.</li><li><strong>Logs API host.</strong> As in v1, the host is picked from the license key&#39;s region (<code>log-api.eu.newrelic.com</code> for EU keys). v1 could only override it with <code>setHost()</code> on the handler; v4 reads <code>NEW_RELIC_LOG_HOST</code>.</li><li><strong>Channel options.</strong> v1 ignored the channel config. The default <code>newrelic</code> channel now has <code>&#39;level&#39; =&gt; &#39;debug&#39;</code> and <code>&#39;buffer&#39; =&gt; true</code>, and the <code>level</code>, <code>bubble</code>, <code>buffer</code> and <code>name</code> options are honored.</li><li><strong>Delivery failures.</strong> When the Logs API cannot be reached or rejects a request, v4 writes the failure to PHP&#39;s error log instead of throwing from the log call, and splits batches bigger than the 1 MB payload limit.</li><li><strong>Batches.</strong> v1 always buffered and never flushed the buffer itself, so a queue worker held its logs until it exited. v4 sends the buffered batch (one JSON array) after each Octane request and queue job, and <code>&#39;buffer&#39; =&gt; false</code> sends each record immediately.</li><li><strong>Metadata.</strong> <code>service</code>, <code>hostname</code>, the client IP and the authenticated user are resolved per record, so they are correct on Octane. The agent&#39;s <code>hostname</code> now wins over the PHP hostname so logs link to the right host entity. A user without a readable email is logged with <code>email: null</code> instead of <code>&#39;guest&#39;</code>, and the user <code>id</code> comes from <code>getAuthIdentifier()</code>.</li><li><strong>Queue transactions.</strong> v4 no longer touches queue job transactions. v1 ended the transaction and started a new one after each processed job and Horizon release, but those listeners run inside the transaction the New Relic agent already opens for each job, so they cut the agent&#39;s job transaction short and left a duplicate, unnamed one. Each job is now reported only by the agent, as a background transaction named <code>JobClass (connection)</code> (for example <code>App\\Jobs\\SendInvoice (redis)</code>) that also records the job&#39;s exception when it fails. The package still sends the buffered logs after each job. If you upgrade from <code>v4.0.0-alpha.1</code>, remove <code>NEW_RELIC_QUEUE_TRANSACTIONS</code> from <code>.env</code> and <code>transactions.queue</code> from a published <code>config/newrelic.php</code>; the setting is gone.</li><li><strong>Octane transactions.</strong> Octane web transactions are reported to <code>NEW_RELIC_APP_NAME</code> when set (v1 always used the agent&#39;s <code>newrelic.appname</code>) and are named after the request&#39;s route (route name, controller action, or method and URI pattern; <code>unknown</code> without a route) instead of the worker script. The Octane listeners can be turned off with <code>newrelic.transactions.octane</code> (<code>NEW_RELIC_OCTANE_TRANSACTIONS</code>).</li></ul>',14)])])}const p=o(c,[["render",d]]);export{u as __pageData,p as default};
